#include <iostream>
#include <stdexcept>
#include <string>
using namespace std;

template <typename T>
class Stack {
    static const int CAPACITY = 100;
    T data[CAPACITY];
    int top;

public:
    Stack() : top(-1) {}

    void push(const T& value) {
        if (top == CAPACITY - 1)
            throw overflow_error("Stack overflow");
        data[++top] = value;
    }

    T pop() {
        if (top == -1)
            throw underflow_error("Stack underflow");
        return data[top--];
    }

    bool isEmpty() const {
        return top == -1;
    }
};

int main() {
    Stack<int> s;
    s.push(10);
    s.push(20);
    cout << s.pop() << endl;        // 20
    cout << s.pop() << endl;        // 10

    Stack<string> names;
    names.push("Dhaka");
    cout << names.pop() << endl;    // Dhaka

    try {
        s.pop();                    // the stack is empty now
    } catch (const underflow_error& e) {
        cout << "Error: " << e.what() << endl;
    }
    return 0;
}

